});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value
        // and is reported as zero characters; a URL outside the allowlist
        // traps at the boundary, which is the host's call, not ours.
        let (fetched, message) = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let n = u32::try_from(body.chars().count()).unwrap_or(u32::MAX);
                (
                    n,
                    format!("heartbeat at {}s: fetched {} characters", seconds, n),
                )
            }
            Err(_) => (
                0u32,
                format!("heartbeat at {}s: fetch failed, 0 characters", seconds),
            ),
        };

        // Notifier: the contract requires `notified == true` on every output.
        // The value reported is the one the notifier actually returned; if the
        // notification was not accepted, no contract-satisfying output exists,
        // so the node traps rather than fabricating the flag.
        let notified = notifier::notify(&message);
        if !notified {
            panic!("notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
